.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ch-space-2);
  border: 1px solid transparent;
  border-radius: var(--ch-component-button-radius);
  font:
    500 var(--ch-fontSize-sm)/1 var(--ch-font-sans),
    sans-serif;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background var(--ch-duration-fast),
    color var(--ch-duration-fast),
    border-color var(--ch-duration-fast);
  text-decoration: none;
}
.ds-button--md {
  height: var(--ch-component-button-height-md);
  padding: 0 var(--ch-space-4);
}
.ds-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.ds-button:focus-visible,
.ds-field-control:focus-within {
  outline: 2px solid var(--ch-semantic-focus);
  outline-offset: 3px;
}
.ds-button--primary {
  background: var(--ch-component-button-bg);
  color: var(--ch-component-button-fg);
}
.ds-button--primary:hover:not(:disabled) {
  background: var(--ch-component-button-bg-hover);
}
@media (prefers-reduced-motion: reduce) {.ds-button {transition:none;}}

