.ds-field {
  display: grid;
  gap: var(--ch-space-2);
  min-width: 0;
}
.ds-field-label {
  font-size: var(--ch-fontSize-sm);
  font-weight: 500;
  color: var(--ch-semantic-foreground);
}
.ds-field-control {
  display: flex;
  align-items: center;
  gap: var(--ch-space-2);
  height: 36px;
  background: var(--ch-component-field-bg);
  border: 1px solid var(--ch-component-field-border);
  border-radius: var(--ch-component-field-radius);
  padding: 0 var(--ch-space-3);
}
.ds-field-control--error {
  border-color: var(--ch-semantic-danger);
}
.ds-field-control:has(input:disabled) {
  opacity: 0.5;
  cursor: not-allowed;
}
.ds-field-control input {
  min-width: 0;
  width: 100%;
  background: transparent;
  color: var(--ch-semantic-foreground);
  border: 0;
  outline: 0;
  font:
    400 var(--ch-fontSize-sm)/1.5 var(--ch-font-sans),
    sans-serif;
}
.ds-field-control input::placeholder {
  color: var(--ch-semantic-muted);
  opacity: 1;
}
.ds-field-leading {
  display: flex;
  color: var(--ch-semantic-muted);
}
.ds-field-leading svg {
  width: 16px;
  height: 16px;
}
.ds-field-help {
  font-size: var(--ch-fontSize-xs);
  color: var(--ch-semantic-muted);
}
.ds-field-error {
  color: var(--ch-semantic-danger);
}
.ds-field {font-family:var(--ch-font-sans),sans-serif;}.ds-field-help {line-height:1.5;} .ds-field-control:focus-within {outline:2px solid var(--ch-semantic-focus);outline-offset:3px;}

.ds-card {
  background: var(--ch-component-card-bg);
  border-radius: var(--ch-component-card-radius);
  min-width: 0;
}
.ds-card--outline {
  border: 1px solid var(--ch-component-card-border);
}
.ds-card--md {
  padding: var(--ch-space-5);
}
.ds-card {font:400 14px/1.5 var(--ch-font-sans),sans-serif;color:var(--ch-semantic-foreground);} .ds-card strong {font-weight:500;} .ds-card p {margin:8px 0 0;color:var(--ch-semantic-muted);}

.ds-badge {
  display: inline-flex;
  align-items: center;
  border-radius: var(--ch-radius-sm);
  font-size: var(--ch-fontSize-xs);
  line-height: 1.5;
  font-weight: 500;
  white-space: nowrap;
  padding: 2px 8px;
}
.ds-badge--accent {
  color: var(--ch-semantic-accent);
  background: var(--ch-semantic-accent-soft);
}
.ds-badge {font-family:var(--ch-font-sans),sans-serif;}

.ds-nav {
  margin-bottom: 28px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.ds-nav a {
  padding: 7px 10px;
  font-size: 13px;
  color: var(--ch-semantic-muted);
  border-radius: 4px;
}
.ds-nav a:hover {
  color: var(--ch-semantic-foreground);
  background: var(--ch-semantic-subtle);
}
.ds-nav a[aria-current] {
  background: var(--ch-semantic-accent-soft);
  color: var(--ch-semantic-accent);
  font-weight: 500;
}
.ds-nav {font-family:var(--ch-font-sans),sans-serif;line-height:1.5;} .ds-nav a {text-decoration:none;} .ds-nav a:focus-visible {outline:2px solid var(--ch-semantic-focus);outline-offset:4px;}

.ds-table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--ch-fontSize-sm);
  text-align: left;
  color: var(--ch-semantic-foreground);
}
.ds-table th {
  height: 40px;
  background: var(--ch-component-table-header-bg);
  font-size: var(--ch-fontSize-xs);
  font-weight: 500;
  color: var(--ch-semantic-muted);
  white-space: nowrap;
}
.ds-table td {
  height: var(--ch-component-table-row-height);
}
.ds-table th,
.ds-table td {
  padding: var(--ch-space-2) var(--ch-space-5);
  border-bottom: 1px solid var(--ch-component-table-border);
}
.ds-table tbody tr:last-child td {
  border-bottom: 0;
}
.ds-table tbody tr:hover {
  background: var(--ch-semantic-inset);
}
.ds-table caption {
  text-align: left;
  padding: var(--ch-space-3) var(--ch-space-5);
  font-size: var(--ch-fontSize-xs);
  color: var(--ch-semantic-muted);
}
.ds-table {font-family:var(--ch-font-sans),sans-serif;line-height:1.5;}
